const auto& node_road_map = this->get_node_to_roadmap();
float best_dist = std::numeric_limits<float>::max();
Node* closest = nullptr;
for (const auto& entry : node_road_map)
{
    int idx = entry.first;
    const Model::Node& model_node = this->SNodes()[idx];
    float dx = model_node.x - x;
    float dy = model_node.y - y;
    float d = std::sqrt(dx * dx + dy * dy);
    if (d < best_dist)
    {
        best_dist = d;
        closest = &this->m_nodes[idx];
    }
}
return closest;

